L_GODA_GRANNAR:;
	CX = 5;	/* MOV cx,no_of_ramps */
L_LUTA:;
	{ uint16_t ea_ = (uint16_t)(BX + 0x2); uint16_t t_ = RD16(DS, ea_); SUB16(t_, 3, FL_NONE); WR16(DS, ea_, t_); }	/* SUB word ptr [bx+2],3 */
