	AL = 0xF;	/* MOV al,15 */
	x_int(0x66);	/* INT 66h */
	CALLN(t3_f_PRINT_PAUSE, 0xABF);	/* CALL PRINT_PAUSE */
	WR8(DS, D_SCAN_CODE, 0xFF);	/* MOV scan_code,-1 */
L_FEELP:;
	{ uint8_t t_ = RD8(DS, D_SCAN_CODE); CMP8(t_, 1, FL_ALL); }	/* CMP scan_code,1 */
	if (C_E) goto L_KAKA_CALAMARES;	/* JE kaka_calamares */
	{ uint8_t t_ = RD8(DS, D_SCAN_CODE); CMP8(t_, 0xFF, (FL_Z)); }	/* CMP scan_code,-1 */
	if (C_E) { X_POLL(); goto L_FEELP; }	/* JE FEELP */
	{ uint8_t t_ = RD8(DS, D_SCAN_CODE); CMP8(t_, 1, FL_ALL); }	/* CMP scan_code,1 */
	if (C_E) goto L_KAKA_CALAMARES;	/* JE kaka_calamares */
L_JUDAS:;
	WR8(DS, D_CALAMARES_DELAY, 0x1E);	/* MOV calamares_delay,30 */
	WR8(DS, D_SCAN_CODE, 0xFF);	/* MOV scan_code,-1 */
	CX = 0;	/* MOV cx,0 */
	AX = 4;	/* MOV AX,4 */
	BX = 3;	/* MOV BX,3 */
	x_int(0x66);	/* INT 66H */
	CMP8(AL, 1, FL_ALL);	/* CMP AL,1 */
	if (C_NE) goto L___L0513;	/* JNE ??L0513 */
	{ X_POLL(); TAIL(t3_f_OUTOFMEMORY); }	/* JMP OUTOFMEMORY */
L___L0513:;
	CMP8(AL, 2, FL_ALL);	/* CMP AL,2 */
	if (C_NE) goto L___L0515;	/* JNE ??L0515 */
	{ X_POLL(); TAIL(t3_f_INIT_ERR); }	/* JMP INIT_ERR */
L___L0515:;
	CALLN(t3_f_RESTORE_AFTER_PAUSE, 0xAD3);	/* CALL RESTORE_AFTER_PAUSE */
	WR8(DS, D_INTERRUPTS_ON, 0xFF);	/* MOV interrupts_on,true */
	WR8(DS, D_PAUSEFLAG, 0);	/* MOV pauseflag,false */
L_NOPAUSE:;
	RETURN_NEAR(0);	/* RETN */
L_LAT_DEN_STA:;
	PUSH16(SEG_DATA);	/* PUSH DATA */
	DS = POP16();	/* POP DS */
	WR8(DS, D_HOLDSTILL, 0xFF);	/* MOV HOLDSTILL,TRUE */
	CALLN(t3_f_RESTORE_AFTER_PAUSE, 0xADA);	/* CALL RESTORE_AFTER_PAUSE */
