	{ uint16_t ea_ = D_MUZIK_OFF; uint8_t t_ = RD8(DS, ea_); XOR8(t_, 0xFF, FL_ALL); WR8(DS, ea_, t_); }	/* XOR muzik_off,true */
	WR8(CS, D_LEVIN, 0xFF);	/* MOV cs:levin,true */
	SI = 0;	/* MOV si,0 */
	PUSH16(SI);	/* PUSH si */
	CX = 0;	/* MOV CX,0 */
	AL = 6;	/* MOV AL,6 */
	x_int(0x66);	/* INT 66H */
