	SI = POP16();	/* POP si */
	CX = 0;	/* MOV cx,0 */
	AX = 4;	/* MOV AX,4 */
	BX = 3;	/* MOV BX,3 */
	x_int(0x66);	/* INT 66H */
	{ X_POLL(); TAIL(t3_f_QUIT); }	/* JMP QUIT */
	WR8(CS, D_QUITTING, 0xFF);	/* MOV CS:QUITTING,TRUE */
	SI = 1;	/* MOV si,1 */
	RETURN_NEAR(0);	/* RETN */
L_KAKA_CALAMARES:;
	PUSH16(D_QUIT_TEXT);	/* PUSH OFFSET quit_TEXT */
