	WR8(DS, D_JINGLEJUMPCNT, 0);	/* MOV JINGLEJUMPCNT,0 */
	goto L_CHECK_M_OFF;	/* JMP check_m_off */
	RETURN_FAR(0);	/* RETF */
L_JINGLEREADY:;
	AL = RD8(DS, D_LASTPRIORITY);	/* MOV AL,LASTPRIORITY */
	WR8(DS, D_CURRENT_PRIORITY, AL);	/* MOV CURRENT_PRIORITY,AL */
	WR8(DS, D_JINGLEJUMPCNT, 0);	/* MOV JINGLEJUMPCNT,0 */
	AL = RD8(DS, D_LASTJINGLE);	/* MOV AL,LASTJINGLE */
	WR8(DS, D_JINGLE_READY_ANIM, 0xFF);	/* MOV JINGLE_READY_ANIM,TRUE */
