	{ uint16_t ea_ = (uint16_t)(BX + 0x6E); uint16_t t_ = RD16(DS, ea_); ADD16(t_, 8, FL_NONE); WR16(DS, ea_, t_); }	/* ADD [bx+size flipstruc].fliptoppek,8 */
	{ uint16_t ea_ = (uint16_t)(BX + 0x70); uint16_t t_ = RD16(DS, ea_); ADD16(t_, 8, FL_NONE); WR16(DS, ea_, t_); }	/* ADD [bx+size flipstruc].flippek,8 */
	{ uint16_t ea_ = (uint16_t)(BX + 0x6C); uint16_t t_ = RD16(DS, ea_); ADD16(t_, 8, FL_NONE); WR16(DS, ea_, t_); }	/* ADD [bx+size flipstruc].flipmaxpek,8 */
	PUSH16(BX);	/* PUSH bx */
