void t3_f_LOAD_THE_FLIPS(void)
{
	SI = 0;	/* MOV si,0 */
	AX = SEG_FLIPGFXSEG;	/* MOV AX,flipgfxseg */
	DS = AX;	/* MOV ds,AX */
	AX = 0xA000;	/* MOV AX,0a000h */
	ES = AX;	/* MOV es,AX */
	DX = 0x3C4;	/* MOV DX,3C4H */
	AH = 1;	/* MOV AH,bipl */
	AL = 2;	/* MOV AL,2 */
	OUT16(DX, AX);	/* OUT DX,AX */
	CX = 0xDC;	/* MOV cx,flipgfxfilesize */
	SHR16(CX, 2, FL_NONE);	/* SHR CX,2 */
	DI = 0xD4F4;	/* MOV DI,GFXADR_FOR_FLIP_ANIM_DATA */
	x_rep_movsb(DS);	/* MOVSB */
	DX = 0x3C4;	/* MOV DX,3C4H */
	AH = 2;	/* MOV AH,bipl */
	AL = 2;	/* MOV AL,2 */
	OUT16(DX, AX);	/* OUT DX,AX */
	CX = 0xDC;	/* MOV cx,flipgfxfilesize */
	SHR16(CX, 2, FL_NONE);	/* SHR CX,2 */
	DI = 0xD4F4;	/* MOV DI,GFXADR_FOR_FLIP_ANIM_DATA */
	x_rep_movsb(DS);	/* MOVSB */
	DX = 0x3C4;	/* MOV DX,3C4H */
	AH = 4;	/* MOV AH,bipl */
	AL = 2;	/* MOV AL,2 */
	OUT16(DX, AX);	/* OUT DX,AX */
	CX = 0xDC;	/* MOV cx,flipgfxfilesize */
	SHR16(CX, 2, FL_NONE);	/* SHR CX,2 */
	DI = 0xD4F4;	/* MOV DI,GFXADR_FOR_FLIP_ANIM_DATA */
	x_rep_movsb(DS);	/* MOVSB */
	DX = 0x3C4;	/* MOV DX,3C4H */
	AH = 8;	/* MOV AH,bipl */
	AL = 2;	/* MOV AL,2 */
	OUT16(DX, AX);	/* OUT DX,AX */
	CX = 0xDC;	/* MOV cx,flipgfxfilesize */
	SHR16(CX, 2, FL_ALL);	/* SHR CX,2 */
	DI = 0xD4F4;	/* MOV DI,GFXADR_FOR_FLIP_ANIM_DATA */
	x_rep_movsb(DS);	/* MOVSB */
	AX = SEG_DATA;	/* MOV AX,data */
	DS = AX;	/* MOV ds,AX */
	RETURN_NEAR(0);	/* RETN */
}

