	SHL16(BX, 4, FL_NONE);	/* SAL BX,4 */
	{ uint16_t ea_ = D_RASTERPOS; uint16_t t_ = RD16(DS, ea_); ADD16(t_, BX, FL_NONE); WR16(DS, ea_, t_); }	/* ADD RASTERPOS,BX */
L_BX_OKI:;
	BX = RD16(DS, D_RASTERPOS);	/* MOV bx,rasterpos */
	SAR16(BX, 4, FL_NONE);	/* SAR bx,4 */
	ADD16(BX, RD16(DS, D_SCREENPOSY), FL_NONE);	/* ADD BX,SCREENPOSY */
	PUSH16(BX);	/* PUSH bx */
	AX = 0x54;	/* MOV AX,SW/4 */
