	{ uint8_t t_ = RD8(DS, D_INTERRUPTS_ON); CMP8(t_, 0xFF, FL_ALL); }	/* CMP INTERRUPTS_ON,TRUE */
	if (C_E) goto L_VBLANKOK;	/* JE VBLANKOK */
