	{ uint16_t ea_ = D_SLUMP_COUNTERN; uint16_t t_ = RD16(DS, ea_); ADD16(t_, 0x406, FL_NONE); WR16(DS, ea_, t_); }	/* ADD SLUMP_COUNTERN,1030 */
