L_HIGH_F3_DONE:;
L_KEEP_COOL:;
	AX = RD16(DS, D_START_RASTER);	/* MOV AX,START_RASTER */
	PUSH16(BP);	/* PUSH BP */
	BP = 0x67;	/* MOV BP,MIDDLE_RASTER_LO */
