void t3_f_DO_THE_ANIMATIONS(void)
{
	{ uint8_t t_ = RD8(DS, D_INTFLAG); CMP8(t_, 0xFF, FL_ALL); }	/* CMP intflag,true */
	if (C_E) goto L_ATERSTALLAREN;	/* JE aterstallaren */
L_LADDANASTA:;
	DX = RD16(DS, D_DOTRUT);	/* MOV DX,DOTRUT */
	SI = RD16(DS, D_SISA);	/* MOV SI,SISA */
	CALLPTR(x_dispatch(CS, DX), 0x1148);	/* CALL DX */
	PUSH16(SEG_DATA);	/* PUSH DATA */
	DS = POP16();	/* POP DS */
	WR16(DS, D_SISA, SI);	/* MOV SISA,SI */
	CMP16(SI, 0, FL_ALL);	/* CMP SI,0 */
	if (C_NE) goto L_NOTFREEYET;	/* JNE NOTFREEYET */
	WR16(DS, D_DOTRUT, C_NODOT);	/* MOV DOTRUT,OFFSET CS:NODOT */
	BX = RD16(DS, D_NEXT_A);	/* MOV BX,NEXT_A */
	CMP16(BX, 0, FL_ALL);	/* CMP BX,0 */
	if (C_E) goto L_TS_SLUT;	/* JE ts_slut */
	CALLN(t3_f_DO_SPEC_MATRIX, 0x1152);	/* CALL DO_SPEC_MATRIX */
	goto L_NOMOREANIMS;	/* JMP nomoreanims */
L_TS_SLUT:;
	CALLN(t3_f_KILL_FLASHOR, 0x1154);	/* CALL KILL_FLASHOR */
L_NOMOREANIMS:;
	WR8(DS, D_DOT_READY, 0xFF);	/* MOV DOT_READY,TRUE */
	goto L_HOPPA_FORBI;	/* JMP HOPPA_FORBI */
L_ATERSTALLAREN:;
	WR8(DS, D_INTFLAG, 0);	/* MOV intflag,false */
	{ X_POLL(); goto L_LADDANASTA; }	/* JMP laddanasta */
L_NOTFREEYET:;
L_HOPPA_FORBI:;
	RETURN_NEAR(0);	/* RETN */
}

