	{ uint16_t ea_ = D_CLEAR_BOX_START; uint16_t t_ = RD16(DS, ea_); ADD16(t_, 0xA8, FL_ALL); WR16(DS, ea_, t_); }	/* ADD clear_box_start,2*sw/4 */
	WR16(DS, D_CLEAR_BOX_BREDD, 0x50);	/* MOV clear_box_bredd,320/4 */
	WR16(DS, D_CLEAR_BOX_HOJD, 1);	/* MOV clear_box_hojd,1 */
	CALLN(t3_f_CLEAR_BOX2, 0x1270);	/* CALL clear_box2 */
L_NORADERING_UPP:;
