	CALLN(t3_f_DOLIGHTS, 0x12EB);	/* CALL DOLIGHTS */
	WR16(DS, D_LAGERARBETAREN, D_PAUSE_LAGRET);	/* MOV LAGERARBETAREN,OFFSET PAUSE_LAGRET */
	WR8(DS, D_LILLE_LAGERARBETAREN, 0x80);	/* MOV LILLE_LAGERARBETAREN,10000000B */
	PUSH16(0xA000);	/* PUSH 0A000H */
	ES = POP16();	/* POP ES */
	CX = 4;	/* MOV CX,4 */
L_PP_NEXT_BITPLANE:;
	PUSH16(CX);	/* PUSH CX */
	AL = 4;	/* MOV AL,4 */
	SUB8(AL, CL, FL_ALL);	/* SUB AL,CL */
	DX = 0x3CE;	/* MOV DX,3CEH */
	AH = AL;	/* MOV AH,AL */
	AL = 4;	/* MOV AL,4 */
	OUT16(DX, AX);	/* OUT DX,AX */
	CALLN(t3_f_PP_DO_BITPLANE, 0x12F8);	/* CALL PP_DO_BITPLANE */
	CX = POP16();	/* POP CX */
	DEC16(CX, (FL_Z | FL_S | FL_O | FL_P | FL_A));	/* DEC CX */
	CX = (uint16_t)(CX - 1);	/* LOOP PP_NEXT_BITPLANE */
	if (CX != 0) { X_POLL(); goto L_PP_NEXT_BITPLANE; }
