	AX = RD16(DS, (uint16_t)(BX + 0x1E));	/* MOV AX,[BX].FLIPFRAME */
	CX = AX;	/* MOV CX,AX */
	SUB16(CX, RD16(DS, (uint16_t)(BX + 0x2C)), FL_ALL);	/* SUB CX,[BX].LASTGFXFRAME */
	{ uint16_t ea_ = (uint16_t)(BX + 0x2C); uint16_t t_ = RD16(DS, ea_); WR16(DS, ea_, AX); AX = t_; }	/* XCHG [BX].LASTGFXFRAME,AX */
	if (C_E) { X_POLL(); TAIL(t3_f_NOMOVE); }	/* JE NOMOVE */
	if (C_A) goto L_WAYUP;	/* JA WAYUP */
	NEG16(CX, FL_NONE);	/* NEG CX */
	DX = RD16(DS, (uint16_t)(BX + 0x38));	/* MOV DX,[BX].FLIPDIFS */
	MUL16(DX);	/* MUL DX */
	PUSH16(RD16(DS, (uint16_t)(BX + 0x30)));	/* PUSH [BX].FLIPMAXPEK */
	WR16(DS, (uint16_t)(BX + 0x34), POP16());	/* POP [BX].FLIPPEK */
	{ uint16_t ea_ = (uint16_t)(BX + 0x34); uint16_t t_ = RD16(DS, ea_); SUB16(t_, AX, FL_NONE); WR16(DS, ea_, t_); }	/* SUB [BX].FLIPPEK,AX */
	goto L_DANIM;	/* JMP DANIM */
L_WAYUP:;
	DX = RD16(DS, (uint16_t)(BX + 0x38));	/* MOV DX,[BX].FLIPDIFS */
	MUL16(DX);	/* MUL DX */
	ADD16(AX, RD16(DS, (uint16_t)(BX + 0x36)), FL_NONE);	/* ADD AX,[BX].FLIPTAB */
	WR16(DS, (uint16_t)(BX + 0x34), AX);	/* MOV [BX].FLIPPEK,AX */
L_DANIM:;
	PUSH16(0);	/* PUSH 0 */
	CMP16(CX, 9, (FL_C | FL_Z));	/* CMP CX,9 */
	if (C_BE) goto L_DELTA_ANIMERA;	/* JBE DELTA_ANIMERA */
	AX = POP16();	/* POP AX */
	AX = CX;	/* MOV AX,CX */
	SUB16(AX, 9, FL_NONE);	/* SUB AX,9 */
	PUSH16(AX);	/* PUSH AX */
	CX = 9;	/* MOV CX,9 */
L_DELTA_ANIMERA:;
	PUSH16(CX);	/* PUSH CX */
	PUSH16(DI);	/* PUSH DI */
	PUSH16(BX);	/* PUSH BX */
	BX = RD16(DS, (uint16_t)(BX + 0x34));	/* MOV BX,[BX].FLIPPEK */
	AX = SEG_DATAFLIP;	/* MOV AX,DATAFLIP */
	DS = AX;	/* MOV DS,AX */
	SI = CX;	/* MOV si,cx */
	DEC16(SI, FL_NONE);	/* DEC si */
	SHL16(SI, 1, FL_NONE);	/* SHL si,1 */
	CX = RD16(DS, (uint16_t)(BX + SI));	/* MOV CX,[BX+si] */
	if (CX == 0) goto L_NOBYTESTOANIM;	/* JCXZ nobytestoanim */
	ADD16(BX, 0x12, FL_ALL);	/* ADD BX,2*9 */
	CALLN(t3_f_DELTANIM, 0x186F);	/* CALL DELTANIM */
L_NOBYTESTOANIM:;
	AX = SEG_DATA;	/* MOV AX,DATA */
	DS = AX;	/* MOV DS,AX */
	BX = POP16();	/* POP BX */
	AX = RD16(DS, (uint16_t)(BX + 0x38));	/* MOV AX,[BX].FLIPDIFS */
	{ uint16_t ea_ = (uint16_t)(BX + 0x34); uint16_t t_ = RD16(DS, ea_); ADD16(t_, AX, FL_NONE); WR16(DS, ea_, t_); }	/* ADD [BX].FLIPPEK,AX */
	DI = POP16();	/* POP DI */
