void t3_f_DOTHISFLASH(void)
{
	DI = SI;	/* MOV DI,SI */
	x_lodsw(DS);	/* LODSW */
	INC16(AX, FL_NONE);	/* INC AX */
	x_stosw();	/* STOSW */
	BP = AX;	/* MOV BP,AX */
	x_lodsw(DS);	/* LODSW */
	DI = AX;	/* MOV DI,AX */
	x_lodsw(DS);	/* LODSW */
	CMP16(BP, AX, FL_ALL);	/* CMP BP,AX */
	if (C_E) goto L_TURNITOFF;	/* JE TURNITOFF */
	x_lodsw(DS);	/* LODSW */
	CMP16(BP, AX, FL_ALL);	/* CMP BP,AX */
	if (C_E) goto L_TURNITON;	/* JE TURNITON */
L_TURNBACK:;
	RETURN_NEAR(0);	/* RETN */
L_TURNITOFF:;
	x_lodsw(DS);	/* LODSW */
	x_lodsw(DS);	/* LODSW */
	BL = AL;	/* MOV BL,AL */
	CALLN(t3_f_DOLOFF, 0x1D7D);	/* CALL DOLOFF */
	{ X_POLL(); goto L_TURNBACK; }	/* JMP TURNBACK */
L_TURNITON:;
	x_lodsw(DS);	/* LODSW */
	PUSH16(SI);	/* PUSH SI */
	PUSH16(DI);	/* PUSH DI */
	PUSH16(ES);	/* PUSH ES */
	BL = AL;	/* MOV BL,AL */
	CALLN(t3_f_DOLON, 0x1D84);	/* CALL DOLON */
	ES = POP16();	/* POP ES */
	AX = POP16();	/* POP AX */
	DI = POP16();	/* POP DI */
	SUB16(DI, 0xA, FL_ALL);	/* SUB DI,10 */
	x_stosw();	/* STOSW */
	{ X_POLL(); goto L_TURNBACK; }	/* JMP TURNBACK */
}

