void t3_f_PELLE_2_BW(void)
{
	SI = D_PALLE;	/* MOV si,offset cs:palle */
	AX = CS;	/* MOV ax,cs */
	ES = AX;	/* MOV es,ax */
	CX = 0x100;	/* MOV cx,256 */
	XOR8(BH, BH, FL_NONE);	/* XOR bh,bh */
L_BMW:;
	BL = RD8(ES, (uint16_t)(SI));	/* MOV bl,es:[si] */
	AX = BX;	/* MOV ax,bx */
	BL = RD8(ES, (uint16_t)(SI + 0x1));	/* MOV bl,es:[si+1] */
	ADD16(AX, BX, FL_NONE);	/* ADD ax,bx */
	BL = RD8(ES, (uint16_t)(SI + 0x2));	/* MOV bl,es:[si+2] */
	ADD16(AX, BX, FL_NONE);	/* ADD ax,bx */
	BL = 3;	/* MOV bl,3 */
	DIV8(BL);	/* DIV bl */
	WR8(ES, (uint16_t)(SI), AL);	/* MOV es:[si],al */
	WR8(ES, (uint16_t)(SI + 0x1), AL);	/* MOV es:[si+1],al */
	WR8(ES, (uint16_t)(SI + 0x2), AL);	/* MOV es:[si+2],al */
	ADD16(SI, 3, FL_ALL);	/* ADD si,3 */
	CX = (uint16_t)(CX - 1);	/* LOOP bmw */
	if (CX != 0) { X_POLL(); goto L_BMW; }
	RETURN_NEAR(0);	/* RETN */
}

void t3_f_COLOR_2_BW(void)
{
	PUSH16(DS);	/* PUSH DS */
	ES = POP16();	/* POP ES */
	SI = D_LON1;	/* MOV SI,OFFSET LON1 */
	CX = 0x27;	/* MOV CX,NOOFLIGHTS+1 */
L_CONV_NEXT_POST:;
	PUSH16(CX);	/* PUSH CX */
	INC16(SI, FL_NONE);	/* INC SI */
	x_lodsb(DS);	/* LODSB */
	XOR8(AH, AH, FL_NONE);	/* XOR AH,AH */
	BL = 3;	/* MOV BL,3 */
	DIV8(BL);	/* DIV BL */
	CX = AX;	/* MOV CX,AX */
L_CONV_NEXT_RGB_BLOCK:;
	PUSH16(CX);	/* PUSH CX */
	DI = SI;	/* MOV DI,SI */
	XOR8(AH, AH, FL_NONE);	/* XOR AH,AH */
	x_lodsb(DS);	/* LODSB */
	DX = AX;	/* MOV DX,AX */
	x_lodsb(DS);	/* LODSB */
	ADD16(DX, AX, FL_NONE);	/* ADD DX,AX */
	x_lodsb(DS);	/* LODSB */
	ADD16(AX, DX, FL_ALL);	/* ADD AX,DX */
	BL = 3;	/* MOV BL,3 */
	DIV8(BL);	/* DIV BL */
	x_stosb();	/* STOSB */
	x_stosb();	/* STOSB */
	x_stosb();	/* STOSB */
	CX = POP16();	/* POP CX */
	CX = (uint16_t)(CX - 1);	/* LOOP CONV_NEXT_RGB_BLOCK */
	if (CX != 0) { X_POLL(); goto L_CONV_NEXT_RGB_BLOCK; }
	CX = POP16();	/* POP CX */
	CX = (uint16_t)(CX - 1);	/* LOOP CONV_NEXT_POST */
	if (CX != 0) { X_POLL(); goto L_CONV_NEXT_POST; }
	RETURN_NEAR(0);	/* RETN */
}

void t3_f_ADDSCOREBCD(void)
{
	AL = RD8(DS, (uint16_t)(DI + 0xB));	/* MOV al,[di+antalsiffror] */
	ADD8(AL, RD8(DS, (uint16_t)(SI + 0xB)), (FL_C | FL_A));	/* ADD al,[si+antalsiffror] */
	x_aaa();	/* AAA */
	WR8(DS, (uint16_t)(DI + 0xB), AL);	/* MOV [di+antalsiffror],al */
	AL = RD8(DS, (uint16_t)(DI + 0xA));	/* MOV al,[di-pos+antalsiffror] */
	ADC8(AL, RD8(DS, (uint16_t)(SI + 0xA)), (FL_C | FL_A));	/* ADC al,[si-pos+antalsiffror] */
	x_aaa();	/* AAA */
	WR8(DS, (uint16_t)(DI + 0xA), AL);	/* MOV [di-pos+antalsiffror],al */
	AL = RD8(DS, (uint16_t)(DI + 0x9));	/* MOV al,[di-pos+antalsiffror] */
	ADC8(AL, RD8(DS, (uint16_t)(SI + 0x9)), (FL_C | FL_A));	/* ADC al,[si-pos+antalsiffror] */
	x_aaa();	/* AAA */
	WR8(DS, (uint16_t)(DI + 0x9), AL);	/* MOV [di-pos+antalsiffror],al */
	AL = RD8(DS, (uint16_t)(DI + 0x8));	/* MOV al,[di-pos+antalsiffror] */
	ADC8(AL, RD8(DS, (uint16_t)(SI + 0x8)), (FL_C | FL_A));	/* ADC al,[si-pos+antalsiffror] */
	x_aaa();	/* AAA */
	WR8(DS, (uint16_t)(DI + 0x8), AL);	/* MOV [di-pos+antalsiffror],al */
	AL = RD8(DS, (uint16_t)(DI + 0x7));	/* MOV al,[di-pos+antalsiffror] */
	ADC8(AL, RD8(DS, (uint16_t)(SI + 0x7)), (FL_C | FL_A));	/* ADC al,[si-pos+antalsiffror] */
	x_aaa();	/* AAA */
	WR8(DS, (uint16_t)(DI + 0x7), AL);	/* MOV [di-pos+antalsiffror],al */
	AL = RD8(DS, (uint16_t)(DI + 0x6));	/* MOV al,[di-pos+antalsiffror] */
	ADC8(AL, RD8(DS, (uint16_t)(SI + 0x6)), (FL_C | FL_A));	/* ADC al,[si-pos+antalsiffror] */
	x_aaa();	/* AAA */
	WR8(DS, (uint16_t)(DI + 0x6), AL);	/* MOV [di-pos+antalsiffror],al */
	AL = RD8(DS, (uint16_t)(DI + 0x5));	/* MOV al,[di-pos+antalsiffror] */
	ADC8(AL, RD8(DS, (uint16_t)(SI + 0x5)), (FL_C | FL_A));	/* ADC al,[si-pos+antalsiffror] */
	x_aaa();	/* AAA */
	WR8(DS, (uint16_t)(DI + 0x5), AL);	/* MOV [di-pos+antalsiffror],al */
	AL = RD8(DS, (uint16_t)(DI + 0x4));	/* MOV al,[di-pos+antalsiffror] */
	ADC8(AL, RD8(DS, (uint16_t)(SI + 0x4)), (FL_C | FL_A));	/* ADC al,[si-pos+antalsiffror] */
	x_aaa();	/* AAA */
	WR8(DS, (uint16_t)(DI + 0x4), AL);	/* MOV [di-pos+antalsiffror],al */
	AL = RD8(DS, (uint16_t)(DI + 0x3));	/* MOV al,[di-pos+antalsiffror] */
	ADC8(AL, RD8(DS, (uint16_t)(SI + 0x3)), (FL_C | FL_A));	/* ADC al,[si-pos+antalsiffror] */
	x_aaa();	/* AAA */
	WR8(DS, (uint16_t)(DI + 0x3), AL);	/* MOV [di-pos+antalsiffror],al */
	AL = RD8(DS, (uint16_t)(DI + 0x2));	/* MOV al,[di-pos+antalsiffror] */
	ADC8(AL, RD8(DS, (uint16_t)(SI + 0x2)), (FL_C | FL_A));	/* ADC al,[si-pos+antalsiffror] */
	x_aaa();	/* AAA */
	WR8(DS, (uint16_t)(DI + 0x2), AL);	/* MOV [di-pos+antalsiffror],al */
	AL = RD8(DS, (uint16_t)(DI + 0x1));	/* MOV al,[di-pos+antalsiffror] */
	ADC8(AL, RD8(DS, (uint16_t)(SI + 0x1)), (FL_C | FL_A));	/* ADC al,[si-pos+antalsiffror] */
	x_aaa();	/* AAA */
	WR8(DS, (uint16_t)(DI + 0x1), AL);	/* MOV [di-pos+antalsiffror],al */
	AL = RD8(DS, (uint16_t)(DI));	/* MOV al,[di-pos+antalsiffror] */
	ADC8(AL, RD8(DS, (uint16_t)(SI)), (FL_C | FL_A));	/* ADC al,[si-pos+antalsiffror] */
	x_aaa();	/* AAA */
	WR8(DS, (uint16_t)(DI), AL);	/* MOV [di-pos+antalsiffror],al */
	RETURN_NEAR(0);	/* RETN */
}

void t3_f_DO_UPDATE_LIGHT(void)
{
	CMP8(AH, 0xFF, FL_ALL);	/* CMP AH,TRUE */
	if (C_E) goto L_ITS_ON;	/* JE ITS_ON */
	BL = AL;	/* MOV BL,AL */
	CALLN(t3_f_DOLIGHTOFF, 0x21B2);	/* CALL DOLIGHTOFF */
	RETURN_NEAR(0);	/* RETN */
L_ITS_ON:;
	BL = AL;	/* MOV BL,AL */
	CALLN(t3_f_DOLIGHTON, 0x21B5);	/* CALL DOLIGHTON */
	RETURN_NEAR(0);	/* RETN */
}

void t3_f_DO_UPDATE_PSTRUC(void)
{
	PUSH16(BX);	/* PUSH BX */
	BL = AL;	/* MOV BL,AL */
	XOR8(BH, BH, FL_NONE);	/* XOR BH,BH */
	AH = 0xFF;	/* MOV AH,TRUE */
	{ uint8_t t_ = RD8(DS, (uint16_t)(BX + D_LIGHTSTATUS)); CMP8(t_, AH, FL_ALL); }	/* CMP LIGHTSTATUS[BX],AH */
	BX = POP16();	/* POP BX */
	if (C_E) goto L_ITS_ON2;	/* JE ITS_ON2 */
	WR8(DS, (uint16_t)(BX), 0);	/* MOV BYTE PTR [BX],FALSE */
	RETURN_NEAR(0);	/* RETN */
L_ITS_ON2:;
	WR8(DS, (uint16_t)(BX), 0xFF);	/* MOV BYTE PTR [BX],TRUE */
	RETURN_NEAR(0);	/* RETN */
}

